package com.example.dopaminecut2.logic.shortform

import org.junit.Assert.assertEquals
import org.junit.Test
import java.util.zip.CRC32

class KakaotalkPreprocessingParityTest {
    @Test
    fun `whole ui tiles match python ui_tiles_v1 for three aspect ratios`() {
        // Generated by Application/ml/kakaotalk/parity.py (Pillow ui_tiles_v1, RGB bytes CRC32).
        val expected = mapOf(
            (108 to 240) to 328960107L,
            (73 to 161) to 2316418412L,
            (98 to 109) to 627412356L
        )
        expected.forEach { (size, crc) ->
            val (width, height) = size
            val input = IntArray(width * height) { index ->
                val x = index % width
                val y = index / width
                (255 shl 24) or (((x * 37 + y * 13) % 256) shl 16) or
                    (((x * 11 + y * 53) % 256) shl 8) or ((x * 71 + y * 7) % 256)
            }
            val tiles = WholeUiTiles.resize(input, width, height)
            val bytes = ByteArray(tiles.size * 3)
            tiles.forEachIndexed { index, color ->
                bytes[index * 3] = (color shr 16).toByte()
                bytes[index * 3 + 1] = (color shr 8).toByte()
                bytes[index * 3 + 2] = color.toByte()
            }
            assertEquals("${width}x$height", crc, CRC32().apply { update(bytes) }.value)
        }
    }
}
